 query.WriteString("END, updated_at=? WHERE chair_id IS NULL AND id IN (");args=append(args,now)
 for i,p:=range pairs {if i>0 {query.WriteByte('"',')};query.WriteByte('?');args=append(args,rides[p.ride].ID)};query.WriteByte(')')
