  for i,item:=range batch {if i>0 {query.WriteByte(',')};query.WriteString(\"(?,?,?,?,?)\");args=append(args,item.ID,item.ChairID,item.Coordinate.Latitude,item.Coordinate.Longitude,item.CreatedAt)}
  _,err:=connection.Exec(query.String(),args...)
  for _,item:=range batch {item.Result<-err}
 }
}
