 if coordinateBatchDelay<=0 {_,err:=connection.ExecContext(ctx,"'`INSERT INTO chair_locations (id,chair_id,latitude,longitude,created_at) VALUES (?,?,?,?,?)`,id,chairID,coordinate.Latitude,coordinate.Longitude,now);return err}
